// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ILiquidityMigrator} from "./interfaces/ILiquidityMigrator.sol";

interface IVotePowerHook {
    function recordFee(address trader, uint256 fee) external;
}

/// @title BondingCurvePoolV2
/// @notice Same constant-product curve as v1 with one addition: every trade
///         fee is reported to VotePower — the fee you pay becomes your
///         voting power for the current epoch («голос за шкуру»).
contract BondingCurvePoolV2 is ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ---------------------------------------------------------- immutables
    IERC20  public immutable token;
    address public immutable factory;
    address public immutable creator;

    uint256 public immutable totalSupply;
    uint256 public immutable saleCap;
    uint256 public immutable virtualEth;
    uint16  public immutable feeBps;
    uint16  public immutable creatorFeeShareBps;

    // ------------------------------------------------------------- state
    uint256 public ethReserve;
    uint256 public tokensSold;
    bool    public graduated;
    bool    public migrated;

    uint256 public protocolFeesAccrued;
    uint256 public creatorFeesAccrued;

    /// @notice Потолок суммарных покупок создателя на этой кривой.
    ///         ~2% от 6.5 ETH: создатель может зайти в свой токен, но не
    ///         скупить низ кривой мешком под слив в выкупы казны.
    uint256 public constant CREATOR_BUY_CAP = 0.13 ether;
    uint256 public creatorSpent;

    // ------------------------------------------------------------- events
    event Buy(address indexed buyer, uint256 ethIn, uint256 tokensOut, uint256 fee);
    event Sell(address indexed seller, uint256 tokensIn, uint256 ethOut, uint256 fee);
    event Graduated(uint256 ethReserve, uint256 dexTokenReserve);
    event Migrated(address indexed migrator, uint256 ethAmount, uint256 tokenAmount);
    event FeesClaimed(address indexed to, uint256 amount, bool isCreator);

    error TradingClosed();
    error CreatorCapExceeded();
    error SlippageExceeded();
    error ZeroAmount();
    error NotGraduated();
    error AlreadyMigrated();
    error NotAuthorized();

    constructor(
        address token_,
        address creator_,
        uint256 totalSupply_,
        uint256 saleCap_,
        uint256 virtualEth_,
        uint16  feeBps_,
        uint16  creatorFeeShareBps_
    ) {
        require(saleCap_ < totalSupply_, "cap>=supply");
        require(token_ != address(0) && creator_ != address(0), "zero addr");
        require(feeBps_ <= 500, "fee>5%");
        require(creatorFeeShareBps_ <= 10_000, "share>100%");
        factory = msg.sender;
        token = IERC20(token_);
        creator = creator_;
        totalSupply = totalSupply_;
        saleCap = saleCap_;
        virtualEth = virtualEth_;
        feeBps = feeBps_;
        creatorFeeShareBps = creatorFeeShareBps_;
    }

    // ------------------------------------------------------------- views

    function spotPrice() external view returns (uint256) {
        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        return (x * 1e18) / y;
    }

    function quoteBuy(uint256 ethInGross) public view returns (uint256 tokensOut) {
        uint256 fee = (ethInGross * feeBps) / 10_000;
        uint256 ethIn = ethInGross - fee;
        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        tokensOut = (y * ethIn) / (x + ethIn);
    }

    function quoteSell(uint256 tokensIn) public view returns (uint256 ethOutGross) {
        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        ethOutGross = (x * tokensIn) / (y + tokensIn);
    }

    // ------------------------------------------------------------- trading

    function buy(uint256 minTokensOut, address recipient)
        external
        payable
        nonReentrant
        returns (uint256 tokensOut)
    {
        if (graduated) revert TradingClosed();
        if (msg.value == 0) revert ZeroAmount();

        // КАП СОЗДАТЕЛЯ. Живёт здесь, а не в фабрике: лимит только на первой
        // покупке обходился в одной транзакции (создать токен без ETH, затем
        // сразу купить напрямую у пула). Ограничиваем суммарные покупки
        // создателя за всё время жизни кривой — иначе он скупает низ кривой
        // и сливает мешок в выкупы казны.
        if (recipient == creator || msg.sender == creator) {
            creatorSpent += msg.value;
            if (creatorSpent > CREATOR_BUY_CAP) revert CreatorCapExceeded();
        }

        uint256 fee = (msg.value * feeBps) / 10_000;
        uint256 ethIn = msg.value - fee;

        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        tokensOut = (y * ethIn) / (x + ethIn);

        uint256 refund;
        uint256 remaining = saleCap - tokensSold;
        if (tokensOut >= remaining) {
            tokensOut = remaining;
            uint256 ethNeeded = (x * tokensOut + (y - tokensOut) - 1) / (y - tokensOut);
            if (ethNeeded > ethIn) ethNeeded = ethIn;
            uint256 grossNeeded = (ethNeeded * 10_000 + (10_000 - feeBps) - 1) / (10_000 - feeBps);
            if (grossNeeded > msg.value) grossNeeded = msg.value;
            refund = msg.value - grossNeeded;
            fee = grossNeeded - ethNeeded;
            ethIn = ethNeeded;
        }

        if (tokensOut < minTokensOut) revert SlippageExceeded();
        if (tokensOut == 0) revert ZeroAmount();

        // effects
        ethReserve += ethIn;
        tokensSold += tokensOut;
        _accrueFees(fee);

        bool willGraduate = tokensSold >= saleCap;
        if (willGraduate) {
            graduated = true;
        }

        // interactions
        _reportFee(msg.sender, fee);
        token.safeTransfer(recipient, tokensOut);
        if (refund > 0) _sendEth(msg.sender, refund);

        emit Buy(recipient, ethIn, tokensOut, fee);
        if (willGraduate) {
            emit Graduated(ethReserve, totalSupply - saleCap);
        }
    }

    function sell(uint256 tokensIn, uint256 minEthOut)
        external
        nonReentrant
        returns (uint256 ethToUser)
    {
        if (graduated) revert TradingClosed();
        if (tokensIn == 0) revert ZeroAmount();

        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        uint256 ethOutGross = (x * tokensIn) / (y + tokensIn);
        if (ethOutGross > ethReserve) ethOutGross = ethReserve;

        uint256 fee = (ethOutGross * feeBps) / 10_000;
        ethToUser = ethOutGross - fee;
        if (ethToUser < minEthOut) revert SlippageExceeded();

        // effects
        ethReserve -= ethOutGross;
        tokensSold -= tokensIn;
        _accrueFees(fee);

        // interactions
        _reportFee(msg.sender, fee);
        token.safeTransferFrom(msg.sender, address(this), tokensIn);
        _sendEth(msg.sender, ethToUser);

        emit Sell(msg.sender, tokensIn, ethToUser, fee);
    }

    // ------------------------------------------------------------- migration

    function migrate() external nonReentrant {
        if (!graduated) revert NotGraduated();
        if (migrated) revert AlreadyMigrated();
        migrated = true;

        address migrator = IFactoryConfigV2(factory).migrator();
        uint256 tokenAmount = totalSupply - saleCap;
        uint256 ethAmount = ethReserve;
        ethReserve = 0;

        token.safeTransfer(migrator, tokenAmount);
        ILiquidityMigrator(migrator).migrate{value: ethAmount}(address(token), tokenAmount);

        emit Migrated(migrator, ethAmount, tokenAmount);
    }

    // ------------------------------------------------------------- fees

    function claimCreatorFees(address to) external nonReentrant {
        if (msg.sender != creator) revert NotAuthorized();
        require(to != address(0), "zero recipient"); // иначе комиссии сгорают
        uint256 amount = creatorFeesAccrued;
        creatorFeesAccrued = 0;
        _sendEth(to, amount);
        emit FeesClaimed(to, amount, true);
    }

    function claimProtocolFees() external nonReentrant {
        address treasury = IFactoryConfigV2(factory).treasury();
        uint256 amount = protocolFeesAccrued;
        protocolFeesAccrued = 0;
        _sendEth(treasury, amount);
        emit FeesClaimed(treasury, amount, false);
    }

    // ------------------------------------------------------------- internal

    function _accrueFees(uint256 fee) internal {
        if (fee == 0) return;
        uint256 creatorCut = (fee * creatorFeeShareBps) / 10_000;
        creatorFeesAccrued += creatorCut;
        protocolFeesAccrued += fee - creatorCut;
    }

    /// @dev Fee => voting power. Never blocks a trade: if the hook is unset,
    ///      has no code, reverts or burns gas, the trade proceeds without
    ///      power accrual. (Без проверки кода revert «нет контракта» не
    ///      ловится catch-ом и замораживал бы все сделки; без лимита газа
    ///      прожорливый хук валил бы сделки по газу.)
    function _reportFee(address trader, uint256 fee) internal {
        address hook = IFactoryConfigV2(factory).votePower();
        if (hook == address(0) || fee == 0 || hook.code.length == 0) return;
        try IVotePowerHook(hook).recordFee{gas: 150_000}(trader, fee) {} catch {}
    }

    function _sendEth(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "ETH send failed");
    }
}

interface IFactoryConfigV2 {
    function migrator() external view returns (address);
    function treasury() external view returns (address);
    function votePower() external view returns (address);
}

BrokerCats.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data)
        external
        returns (bytes4);
}

interface ICatVaultHook {
    function register(uint256 id) external;
}

interface ICatRenderer {
    function tokenURI(uint256 id, string calldata ticker, uint8 rarity) external view returns (string memory);
}

/// @title BrokerCats — NFT-коты, привязанные к реальным акциям
/// @notice Фэнтези-спорт на токенизированных акциях Robinhood Chain:
///         минт кота случайно назначает тикер (из ростера) и редкость-множитель.
///         Ежедневные результаты считаются по реальным движениям акций
///         (Chainlink-фиды) и публикуются офф-чейн ботом — как очки Арены.
///         НИКАКОЙ «доходности» контракт не обещает и не платит: награды
///         подиуму приходят из казны существующим механизмом выкупов.
///
/// @dev    ERC721 реализован минимально и без внешних библиотек: свежий
///         OpenZeppelin ERC721 требует Cancun (mcopy), а мы собираемся под
///         paris ради совместимости с L2. Логика стандартная: owner/approve/
///         transfer/safeTransfer + метаданные через baseURI.
///         Случайность минта — blockhash+id: для игровой редкости достаточно
///         (манипуляция ради Legendary-кота дороже кота); для денежных лотерей
///         использовали бы VRF.
contract BrokerCats is Ownable {
    // ------------------------------------------------------------- ERC721 core
    string public constant name = "hood Broker Cats";
    string public constant symbol = "HCAT";

    mapping(uint256 => address) private _ownerOf;
    mapping(address => uint256) public balanceOf;
    mapping(uint256 => address) public getApproved;
    mapping(address => mapping(address => bool)) public isApprovedForAll;

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);

    // ------------------------------------------------------------- game data
    struct Roster {
        string ticker;   // "NVDA"
        address feed;    // Chainlink AggregatorV3 этой акции (для UI и ботов)
    }

    struct Cat {
        uint16 rosterId;
        uint8 rarity;    // 0 Common ×1 · 1 Rare ×2 · 2 Epic ×3 · 3 Mythic ×5 · 4 Legendary ×8
    }

    /// @notice Потолок коллекции = 10 000 кейсов (CatBox.MAX_BOXES) + 500 на
    ///         бесплатную раздачу. Считается от кейсов, иначе последние
    ///         купленные боксы не смогли бы открыться: минт упал бы на
    ///         «sold out», а деньги за бокс уже были бы списаны.
    uint256 public constant MAX_SUPPLY = 10_500;
    /// @notice Лимит бесплатной раздачи первым пользователям (аирдроп).
    uint256 public constant AIRDROP_CAP = 500;
    uint256 public immutable mintPrice;
    address public immutable proceeds;

    /// @notice Хранилище дивидендов (CatStockVault). Ставится один раз;
    ///         каждый новый кот регистрируется в нём при минте.
    address public vault;

    /// @notice Контракт кейсов (CatBox) — единственный, кто может минтить
    ///         кота с заранее выпавшей редкостью. Ставится один раз.
    address public box;

    /// @notice Он-чейн рендерер метаданных (CatRenderer). Ноль = метаданные
    ///         берутся по baseURI. Меняется владельцем: картинку можно
    ///         улучшить, не трогая сам NFT-контракт и владение котами.
    address public renderer;

    Roster[] public roster;
    mapping(uint256 => Cat) public catOf;
    uint256 public totalMinted;
    uint256 public airdropped;
    string public baseURI;

    event CatMinted(address indexed to, uint256 indexed id, uint16 rosterId, uint8 rarity, bool free);
    event RosterAdded(uint16 indexed id, string ticker, address feed);
    event VaultSet(address vault);
    event BoxSet(address box);
    event RendererSet(address renderer);

    constructor(uint256 mintPrice_, address proceeds_, string memory baseURI_) Ownable(msg.sender) {
        require(proceeds_ != address(0), "zero proceeds");
        require(mintPrice_ > 0, "zero price");
        mintPrice = mintPrice_;
        proceeds = proceeds_;
        baseURI = baseURI_;
    }

    // ------------------------------------------------------------- admin

    function addRoster(string calldata ticker, address feed) external onlyOwner {
        require(roster.length < 64, "roster full");
        roster.push(Roster(ticker, feed));
        emit RosterAdded(uint16(roster.length - 1), ticker, feed);
    }

    function setBaseURI(string calldata uri) external onlyOwner {
        baseURI = uri;
    }

    /// @notice Привязать он-чейн рендерер метаданных. В отличие от vault и
    ///         box, меняется свободно: это только картинка, на владение и
    ///         дивиденды он не влияет. Ноль возвращает работу через baseURI.
    function setRenderer(address renderer_) external onlyOwner {
        renderer = renderer_;
        emit RendererSet(renderer_);
    }

    /// @notice Однократно привязать хранилище дивидендов.
    function setVault(address vault_) external onlyOwner {
        require(vault == address(0), "already set");
        require(vault_ != address(0), "zero vault");
        vault = vault_;
        emit VaultSet(vault_);
    }

    /// @notice Однократно привязать контракт кейсов.
    function setBox(address box_) external onlyOwner {
        require(box == address(0), "already set");
        require(box_ != address(0), "zero box");
        box = box_;
        emit BoxSet(box_);
    }

    function rosterCount() external view returns (uint256) {
        return roster.length;
    }

    // ------------------------------------------------------------- mint

    /// @notice Прямой минт: фикс-цена, случайный тикер и редкость. Выручка
    ///         сразу уходит в proceeds — на контракте деньги не лежат.
    /// @dev    Как только привязан бокс, прямой минт закрывается: иначе он
    ///         съедал бы supply, зарезервированный под уже проданные кейсы,
    ///         и часть боксов не смогла бы открыться.
    function mint() external payable returns (uint256 id) {
        require(box == address(0), "use box");
        require(msg.value == mintPrice, "wrong price");
        id = _mintCat(msg.sender, false);
        (bool ok, ) = proceeds.call{value: msg.value}("");
        require(ok, "proceeds send failed");
    }

    /// @notice Минт из кейса (CatBox): редкость решает бокс (commit-reveal),
    ///         тикер — сид оттуда же. Звать может только привязанный бокс.
    function mintFromBox(address to, uint8 rarity, uint256 seed) external returns (uint256 id) {
        require(msg.sender == box && box != address(0), "not box");
        require(rarity <= 4, "bad rarity");
        require(totalMinted < MAX_SUPPLY, "sold out");
        require(roster.length > 0, "roster empty");

        id = ++totalMinted;
        catOf[id] = Cat(uint16(seed % roster.length), rarity);
        _mint(to, id);
        emit CatMinted(to, id, catOf[id].rosterId, rarity, false);

        if (vault != address(0)) ICatVaultHook(vault).register(id);
    }

    /// @notice Бесплатная раздача первым пользователям. Только owner,
    ///         жёсткий кап AIRDROP_CAP — «напечатать себе бесплатных котов
    ///         без ограничений» невозможно даже владельцу.
    function airdrop(address[] calldata to) external onlyOwner {
        require(airdropped + to.length <= AIRDROP_CAP, "airdrop cap");
        airdropped += to.length;
        for (uint256 i = 0; i < to.length; i++) {
            _mintCat(to[i], true);
        }
    }

    function _mintCat(address to, bool free) internal returns (uint256 id) {
        require(totalMinted < MAX_SUPPLY, "sold out");
        require(roster.length > 0, "roster empty");

        id = ++totalMinted;

        uint256 rnd = uint256(keccak256(abi.encodePacked(
            blockhash(block.number - 1), to, id
        )));
        catOf[id] = Cat(uint16(rnd % roster.length), _rollRarity(uint8((rnd >> 128) % 100)));

        _mint(to, id);
        emit CatMinted(to, id, catOf[id].rosterId, catOf[id].rarity, free);

        // регистрация в дивидендах: не блокируем минт, если хранилища ещё нет
        if (vault != address(0)) {
            ICatVaultHook(vault).register(id);
        }
    }

    /// @dev 5 уровней. Common 60% ×1 · Rare 24% ×2 · Epic 10% ×3 ·
    ///      Mythic 5% ×5 · Legendary 1% ×8 (roll 0..99: 99 => Legendary).
    function _rollRarity(uint8 roll) internal pure returns (uint8) {
        if (roll < 60) return 0; // 0..59  → 60%
        if (roll < 84) return 1; // 60..83 → 24%
        if (roll < 94) return 2; // 84..93 → 10%
        if (roll < 99) return 3; // 94..98 → 5%
        return 4;                // 99     → 1%
    }

    function rarityMultiplier(uint8 rarity) public pure returns (uint8) {
        if (rarity == 0) return 1;
        if (rarity == 1) return 2;
        if (rarity == 2) return 3;
        if (rarity == 3) return 5;
        return 8; // Legendary
    }

    /// @notice Кот целиком: тикер, фид, редкость — одним вызовом для фронта.
    function catInfo(uint256 id)
        external
        view
        returns (string memory ticker, address feed, uint8 rarity, uint8 multiplier)
    {
        require(_ownerOf[id] != address(0), "no cat");
        Cat memory c = catOf[id];
        Roster memory r = roster[c.rosterId];
        return (r.ticker, r.feed, c.rarity, rarityMultiplier(c.rarity));
    }

    // ------------------------------------------------------------- ERC721

    function ownerOf(uint256 tokenId) public view returns (address o) {
        o = _ownerOf[tokenId];
        require(o != address(0), "no token");
    }

    function approve(address to, uint256 tokenId) external {
        address o = ownerOf(tokenId);
        require(msg.sender == o || isApprovedForAll[o][msg.sender], "not authorized");
        getApproved[tokenId] = to;
        emit Approval(o, to, tokenId);
    }

    function setApprovalForAll(address operator, bool approved) external {
        isApprovedForAll[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        address o = ownerOf(tokenId);
        require(o == from, "wrong from");
        require(to != address(0), "zero to");
        require(
            msg.sender == o || msg.sender == getApproved[tokenId] || isApprovedForAll[o][msg.sender],
            "not authorized"
        );
        delete getApproved[tokenId];
        unchecked {
            balanceOf[from] -= 1;
            balanceOf[to] += 1;
        }
        _ownerOf[tokenId] = to;
        emit Transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        transferFrom(from, to, tokenId);
        _checkReceiver(from, to, tokenId, data);
    }

    /// @notice Метаданные кота. Если привязан рендерер — картинка и JSON
    ///         собираются прямо в блокчейне из редкости и тикера. Иначе
    ///         работает обычный baseURI + id (запасной путь).
    function tokenURI(uint256 tokenId) external view returns (string memory) {
        require(_ownerOf[tokenId] != address(0), "no token");
        if (renderer != address(0)) {
            Cat memory c = catOf[tokenId];
            return ICatRenderer(renderer).tokenURI(tokenId, roster[c.rosterId].ticker, c.rarity);
        }
        return string(abi.encodePacked(baseURI, _toString(tokenId)));
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x80ac58cd // ERC721
            || interfaceId == 0x5b5e139f // ERC721Metadata
            || interfaceId == 0x01ffc9a7; // ERC165
    }

    // ------------------------------------------------------------- internal

    function _mint(address to, uint256 tokenId) internal {
        require(_ownerOf[tokenId] == address(0), "exists");
        unchecked { balanceOf[to] += 1; }
        _ownerOf[tokenId] = to;
        emit Transfer(address(0), to, tokenId);
        _checkReceiver(address(0), to, tokenId, "");
    }

    function _checkReceiver(address from, address to, uint256 tokenId, bytes memory data) private {
        if (to.code.length > 0) {
            require(
                IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data)
                    == IERC721Receiver.onERC721Received.selector,
                "unsafe receiver"
            );
        }
    }

    function _toString(uint256 v) private pure returns (string memory) {
        if (v == 0) return "0";
        uint256 tmp = v;
        uint256 len;
        while (tmp > 0) { len++; tmp /= 10; }
        bytes memory out = new bytes(len);
        while (v > 0) {
            out[--len] = bytes1(uint8(48 + (v % 10)));
            v /= 10;
        }
        return string(out);
    }
}

BuybackTreasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IBuyablePool {
    function buy(uint256 minTokensOut, address recipient) external payable returns (uint256);
    function token() external view returns (IERC20);
}

interface IPoolRegistry {
    function poolOf(address token) external view returns (address);
}

/// @title BuybackTreasury
/// @notice The platform's share of trading fees (80%) flows here, and the
///         ETH can leave ONLY through token buybacks — there is no
///         withdrawal function by design. The owner selectively picks
///         which token to buy back and how much ETH to spend. Bought
///         tokens can be burned (sent to the dead address) for verifiable
///         deflation, or held by the treasury.
contract BuybackTreasury is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    IPoolRegistry public immutable factory;

    uint256 public totalReceived;   // lifetime ETH received
    uint256 public totalSpent;      // lifetime ETH spent on buybacks
    mapping(address => uint256) public boughtOf;  // token => tokens bought
    mapping(address => uint256) public burnedOf;  // token => tokens burned

    event Received(address indexed from, uint256 amount);
    event Buyback(address indexed token, address indexed pool, uint256 ethIn, uint256 tokensOut);
    event Burned(address indexed token, uint256 amount);

    error UnknownToken();
    error InsufficientTreasury();

    constructor(address factory_) Ownable(msg.sender) {
        factory = IPoolRegistry(factory_);
    }

    receive() external payable {
        totalReceived += msg.value;
        emit Received(msg.sender, msg.value);
    }

    /// @notice Selectively buy back `token` on its bonding curve with
    ///         `ethAmount` from the treasury. Owner-only by design —
    ///         the platform picks which coins to support.
    function buyback(address token, uint256 ethAmount, uint256 minTokensOut)
        external
        onlyOwner
        nonReentrant
        returns (uint256 tokensOut)
    {
        if (ethAmount > address(this).balance) revert InsufficientTreasury();
        address pool = factory.poolOf(token);
        if (pool == address(0)) revert UnknownToken();

        tokensOut = IBuyablePool(pool).buy{value: ethAmount}(minTokensOut, address(this));
        totalSpent += ethAmount;
        boughtOf[token] += tokensOut;
        emit Buyback(token, pool, ethAmount, tokensOut);
    }

    /// @notice Burn treasury-held tokens forever (verifiable deflation).
    function burn(address token, uint256 amount) external onlyOwner nonReentrant {
        IERC20(token).safeTransfer(DEAD, amount);
        burnedOf[token] += amount;
        emit Burned(token, amount);
    }

    function treasuryBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

BuybackTreasuryV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IBuyablePool {
    function buy(uint256 minTokensOut, address recipient) external payable returns (uint256);
}

interface IPoolRegistry {
    function poolOf(address token) external view returns (address);
}

interface IVotePowerFund {
    function fundReward(uint256 epochId, address token, uint256 amount) external;
}

/// @title BuybackTreasuryV2 — казна, которая платит голосовавшим
/// @notice The protocol's fee share flows here. ETH can leave ONLY through
///         buybacks — no withdrawal function exists by design. New in v2:
///         a configurable share of every buyback is distributed to the
///         traders who voted for the winning token (via VotePower), the
///         rest is burned. The treasury also keeps an on-chain registry of
///         every token it ever bought — the future hood index reads it.
contract BuybackTreasuryV2 is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    IPoolRegistry public immutable factory;
    address public votePower;               // set once after deploy
    /// @notice Share of bought tokens sent to voters. 0 by design: voters'
    ///         reward IS the buyback+burn pump of the token they voted for.
    ///         Kept configurable in case the community votes it in later.
    uint16  public rewardBps = 0;

    uint256 public totalReceived;
    uint256 public totalSpent;
    mapping(address => uint256) public boughtOf;
    mapping(address => uint256) public burnedOf;
    mapping(address => uint256) public rewardedOf;   // token => sent to voters

    // -------- portfolio registry (для будущего индекса) --------
    address[] public portfolio;                       // every token ever bought
    mapping(address => bool) public inPortfolio;
    mapping(address => bool) public delisted;         // guardian-excluded

    event Received(address indexed from, uint256 amount);
    event Buyback(address indexed token, address indexed pool, uint256 ethIn, uint256 tokensOut);
    event VotersRewarded(uint256 indexed epochId, address indexed token, uint256 amount);
    event Burned(address indexed token, uint256 amount);
    event PortfolioAdded(address indexed token);
    event Delisted(address indexed token, string reason);
    event Relisted(address indexed token);

    error UnknownToken();
    error InsufficientTreasury();
    error AlreadySet();
    error TokenDelisted();

    constructor(address factory_) Ownable(msg.sender) {
        factory = IPoolRegistry(factory_);
    }

    receive() external payable {
        totalReceived += msg.value;
        emit Received(msg.sender, msg.value);
    }

    /// @notice One-time wiring: VotePower is deployed after the treasury.
    function setVotePower(address votePower_) external onlyOwner {
        if (votePower != address(0)) revert AlreadySet();
        require(votePower_ != address(0), "zero addr");
        votePower = votePower_;
    }

    function setRewardBps(uint16 rewardBps_) external onlyOwner {
        require(rewardBps_ <= 10_000, "bps>100%");
        rewardBps = rewardBps_;
    }

    // ------------------------------------------------------------- buyback

    /// @notice Buy back `token`, send `rewardBps` of the bought tokens to
    ///         the voters of finished epoch `epochId` and burn the rest.
    function buybackAndReward(
        address token,
        uint256 ethAmount,
        uint256 minTokensOut,
        uint256 epochId
    ) external onlyOwner nonReentrant returns (uint256 tokensOut) {
        tokensOut = _buy(token, ethAmount, minTokensOut);

        uint256 toVoters = (tokensOut * rewardBps) / 10_000;
        uint256 toBurn = tokensOut - toVoters;

        if (toVoters > 0 && votePower != address(0)) {
            IERC20(token).safeTransfer(votePower, toVoters);
            IVotePowerFund(votePower).fundReward(epochId, token, toVoters);
            rewardedOf[token] += toVoters;
            emit VotersRewarded(epochId, token, toVoters);
        }
        if (toBurn > 0) {
            IERC20(token).safeTransfer(DEAD, toBurn);
            burnedOf[token] += toBurn;
            emit Burned(token, toBurn);
        }
    }

    /// @notice Plain buyback into the treasury portfolio (no distribution).
    function buyback(address token, uint256 ethAmount, uint256 minTokensOut)
        external
        onlyOwner
        nonReentrant
        returns (uint256 tokensOut)
    {
        tokensOut = _buy(token, ethAmount, minTokensOut);
    }

    /// @notice Burn treasury-held tokens (verifiable deflation).
    function burn(address token, uint256 amount) external onlyOwner nonReentrant {
        IERC20(token).safeTransfer(DEAD, amount);
        burnedOf[token] += amount;
        emit Burned(token, amount);
    }

    // ------------------------------------------------------------- guardian

    /// @notice Guardian: exclude a token from the (future) index — safety
    ///         valve for dead or manipulated tokens. On-chain and public.
    function delist(address token, string calldata reason) external onlyOwner {
        delisted[token] = true;
        emit Delisted(token, reason);
    }

    function relist(address token) external onlyOwner {
        delisted[token] = false;
        emit Relisted(token);
    }

    // ------------------------------------------------------------- views

    function treasuryBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function portfolioCount() external view returns (uint256) {
        return portfolio.length;
    }

    /// @notice Token holdings of the treasury (index NAV building block).
    function heldOf(address token) external view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }

    // ------------------------------------------------------------- internal

    function _buy(address token, uint256 ethAmount, uint256 minTokensOut)
        internal
        returns (uint256 tokensOut)
    {
        if (ethAmount > address(this).balance) revert InsufficientTreasury();
        // Делистнутый токен выкупать нельзя — раньше флаг ни на что не влиял
        // и был лишь косметикой в интерфейсе.
        if (delisted[token]) revert TokenDelisted();
        address pool = factory.poolOf(token);
        if (pool == address(0)) revert UnknownToken();

        tokensOut = IBuyablePool(pool).buy{value: ethAmount}(minTokensOut, address(this));
        totalSpent += ethAmount;
        boughtOf[token] += tokensOut;
        if (!inPortfolio[token]) {
            inPortfolio[token] = true;
            portfolio.push(token);
            emit PortfolioAdded(token);
        }
        emit Buyback(token, pool, ethAmount, tokensOut);
    }
}

BuybackVote.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title BuybackVote
/// @notice Weekly advisory poll: which token should the treasury buy back?
///         One wallet — one vote per weekly epoch. Votes are events signed
///         by the voter's wallet: impossible to forge, free to read, stored
///         in the chain forever. The poll is advisory — the platform owner
///         makes the final buyback call (and says so in the UI).
contract BuybackVote {
    uint256 public constant EPOCH_LENGTH = 7 days;

    event Vote(address indexed token, address indexed voter, uint256 indexed epoch);

    mapping(uint256 => mapping(address => bool)) public voted;

    error AlreadyVoted();
    error ZeroToken();

    function epoch() public view returns (uint256) {
        return block.timestamp / EPOCH_LENGTH;
    }

    /// @notice Seconds until the current round ends.
    function epochEndsIn() external view returns (uint256) {
        return EPOCH_LENGTH - (block.timestamp % EPOCH_LENGTH);
    }

    function vote(address token) external {
        if (token == address(0)) revert ZeroToken();
        uint256 e = epoch();
        if (voted[e][msg.sender]) revert AlreadyVoted();
        voted[e][msg.sender] = true;
        emit Vote(token, msg.sender, e);
    }
}

