// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface ICatsMintable {
    function mintFromBox(address to, uint8 rarity, uint256 seed) external returns (uint256 id);
}

/// @title CatBox — кейсы с котами (CS:GO-style), лимит 10 000 на всю игру
/// @notice Игрок покупает бокс, затем открывает его во ВТОРОЙ транзакции.
///         Рандом — commit-reveal: сид складывается из хэша будущего блока
///         (неизвестного на момент покупки) и адреса игрока. Ни игрок, ни
///         майнер не могут подобрать выигрыш: игрок не знает будущий блок,
///         а блок уже зафиксирован до открытия и не выбирается заново.
///
/// @dev    Шансы совпадают с BrokerCats: Common 60 / Rare 24 / Epic 10 /
///         Mythic 5 / Legendary 1 (%). Выручка уходит в proceeds (казна) сразу
///         при покупке. Открывать можно не раньше следующего блока и не позже
///         REVEAL_WINDOW блоков — иначе бокс переоткрывается с новым коммитом
///         (иначе сид стал бы недоступен: blockhash хранится 256 блоков).
contract CatBox is ReentrancyGuard {
    uint256 public constant MAX_BOXES = 10_000;
    uint256 public constant REVEAL_WINDOW = 200; // блоков на открытие

    ICatsMintable public immutable cats;
    address public immutable proceeds;
    uint256 public immutable boxPrice;

    uint256 public sold;      // куплено боксов (лимит 10k)
    uint256 public opened;    // открыто боксов

    struct Box {
        address owner;
        uint64 commitBlock; // блок покупки; сид = blockhash(commitBlock+1)
        bool opened;
    }

    mapping(uint256 => Box) public boxOf; // boxId => бокс
    mapping(address => uint256[]) private _boxesOf;

    event BoxBought(address indexed buyer, uint256 indexed boxId, uint64 commitBlock);
    event BoxOpened(address indexed opener, uint256 indexed boxId, uint256 catId, uint8 rarity);
    event BoxRecommitted(uint256 indexed boxId, uint64 newCommitBlock);

    error SoldOut();
    error WrongPrice();
    error NotOwner();
    error AlreadyOpened();
    error TooEarly();
    error Expired();

    constructor(address cats_, address proceeds_, uint256 boxPrice_) {
        require(cats_ != address(0) && proceeds_ != address(0), "zero addr");
        require(boxPrice_ > 0, "zero price");
        cats = ICatsMintable(cats_);
        proceeds = proceeds_;
        boxPrice = boxPrice_;
    }

    // ------------------------------------------------------------- покупка

    /// @notice Купить бокс. Открыть можно начиная со следующего блока.
    function buy() external payable nonReentrant returns (uint256 boxId) {
        if (msg.value != boxPrice) revert WrongPrice();
        if (sold >= MAX_BOXES) revert SoldOut();

        boxId = ++sold;
        boxOf[boxId] = Box({ owner: msg.sender, commitBlock: uint64(block.number), opened: false });
        _boxesOf[msg.sender].push(boxId);

        emit BoxBought(msg.sender, boxId, uint64(block.number));

        (bool ok, ) = proceeds.call{value: msg.value}("");
        require(ok, "proceeds send failed");
    }

    // ------------------------------------------------------------- открытие

    /// @notice Открыть бокс: минтит кота случайной редкости владельцу бокса.
    function open(uint256 boxId) external nonReentrant returns (uint256 catId, uint8 rarity) {
        Box storage b = boxOf[boxId];
        if (b.owner != msg.sender) revert NotOwner();
        if (b.opened) revert AlreadyOpened();

        uint256 target = uint256(b.commitBlock) + 1;
        if (block.number <= target) revert TooEarly();
        if (block.number > target + REVEAL_WINDOW) revert Expired();

        bytes32 bh = blockhash(target);
        // подстраховка: если хэш недоступен (не должен, окно < 256) — переоткрыть
        if (bh == bytes32(0)) revert Expired();

        b.opened = true;
        opened += 1;

        uint256 seed = uint256(keccak256(abi.encodePacked(bh, msg.sender, boxId)));
        rarity = _rollRarity(uint8(seed % 100));
        catId = cats.mintFromBox(msg.sender, rarity, seed);

        emit BoxOpened(msg.sender, boxId, catId, rarity);
    }

    /// @notice Если окно открытия пропущено — заново зафиксировать блок.
    ///         Бокс не сгорает: игрок не теряет покупку из-за простоя.
    function recommit(uint256 boxId) external {
        Box storage b = boxOf[boxId];
        if (b.owner != msg.sender) revert NotOwner();
        if (b.opened) revert AlreadyOpened();
        uint256 target = uint256(b.commitBlock) + 1;
        require(block.number > target + REVEAL_WINDOW, "still openable");
        b.commitBlock = uint64(block.number);
        emit BoxRecommitted(boxId, uint64(block.number));
    }

    /// @dev Common 60% · Rare 24% · Epic 10% · Mythic 5% · Legendary 1%
    function _rollRarity(uint8 roll) internal pure returns (uint8) {
        if (roll < 60) return 0;
        if (roll < 84) return 1;
        if (roll < 94) return 2;
        if (roll < 99) return 3;
        return 4;
    }

    // ------------------------------------------------------------- views

    function boxesLeft() external view returns (uint256) {
        return MAX_BOXES - sold;
    }

    function boxesOf(address user) external view returns (uint256[] memory) {
        return _boxesOf[user];
    }

    /// @notice Готов ли бокс к открытию прямо сейчас (для UI).
    function openable(uint256 boxId) external view returns (bool ready, bool expired) {
        Box memory b = boxOf[boxId];
        if (b.owner == address(0) || b.opened) return (false, false);
        uint256 target = uint256(b.commitBlock) + 1;
        expired = block.number > target + REVEAL_WINDOW;
        ready = block.number > target && !expired;
    }
}

CatMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface ICatsNFT {
    function ownerOf(uint256 id) external view returns (address);
    function transferFrom(address from, address to, uint256 id) external;
    function catOf(uint256 id) external view returns (uint16 rosterId, uint8 rarity);
}

/// @title CatMarket — биржа NFT-котов hood
/// @notice Простой эскроу-маркетплейс: продавец листит кота (кот переезжает
///         на контракт), покупатель платит нативной монетой, 2% уходит казне,
///         остальное продавцу, кот — покупателю. Отмена возвращает кота.
///         Дивиденды кота (CatStockVault) копятся НА КОТЕ, поэтому при
///         продаже они автоматически переходят покупателю — это часть цены.
/// @dev    Эскроу вместо approve-модели сознательно: рынок маленький, зато
///         листинг невозможно «увести» перепродажей мимо биржи, и все
///         активные лоты тривиально перечисляются он-чейн без индексера.
contract CatMarket is ReentrancyGuard {
    uint16 public constant FEE_BPS = 200; // 2% с продажи — в казну
    uint16 public constant BPS = 10_000;

    ICatsNFT public immutable cats;
    address public immutable treasury;

    struct Listing {
        address seller;
        uint96 price; // до ~79 млрд ETH — за глаза
    }

    mapping(uint256 => Listing) public listingOf; // catId => лот (seller=0 — нет)
    uint256[] private _listed;                    // активные id (с дырками после снятия)
    mapping(uint256 => uint256) private _listedIdx;

    event Listed(uint256 indexed id, address indexed seller, uint256 price);
    event Cancelled(uint256 indexed id, address indexed seller);
    event Bought(uint256 indexed id, address indexed buyer, address indexed seller, uint256 price, uint256 fee);

    error NotSeller();
    error NotListed();
    error WrongPrice();
    error ZeroPrice();

    constructor(address cats_, address treasury_) {
        require(cats_ != address(0) && treasury_ != address(0), "zero addr");
        cats = ICatsNFT(cats_);
        treasury = treasury_;
    }

    // ------------------------------------------------------------- листинг

    /// @notice Выставить кота на продажу. Нужен approve на этот контракт.
    function list(uint256 id, uint96 price) external nonReentrant {
        if (price == 0) revert ZeroPrice();
        cats.transferFrom(msg.sender, address(this), id); // эскроу
        listingOf[id] = Listing(msg.sender, price);
        _listedIdx[id] = _listed.length;
        _listed.push(id);
        emit Listed(id, msg.sender, price);
    }

    /// @notice Снять кота с продажи — он возвращается продавцу.
    function cancel(uint256 id) external nonReentrant {
        Listing memory l = listingOf[id];
        if (l.seller == address(0)) revert NotListed();
        if (l.seller != msg.sender) revert NotSeller();
        _remove(id);
        cats.transferFrom(address(this), msg.sender, id);
        emit Cancelled(id, msg.sender);
    }

    /// @notice Купить кота по цене лота. 2% — казне, остальное продавцу.
    function buy(uint256 id) external payable nonReentrant {
        Listing memory l = listingOf[id];
        if (l.seller == address(0)) revert NotListed();
        if (msg.value != l.price) revert WrongPrice();
        _remove(id);

        uint256 fee = (msg.value * FEE_BPS) / BPS;
        (bool okT, ) = treasury.call{value: fee}("");
        require(okT, "fee send failed");
        (bool okS, ) = l.seller.call{value: msg.value - fee}("");
        require(okS, "seller send failed");

        cats.transferFrom(address(this), msg.sender, id);
        emit Bought(id, msg.sender, l.seller, msg.value, fee);
    }

    // ------------------------------------------------------------- views

    function listedCount() external view returns (uint256) {
        return _listed.length;
    }

    /// @notice Страница активных лотов для фронта: id, продавец, цена, редкость.
    function listings(uint256 offset, uint256 limit)
        external
        view
        returns (uint256[] memory ids, address[] memory sellers, uint256[] memory prices, uint8[] memory rarities)
    {
        uint256 n = _listed.length;
        if (offset >= n) return (new uint256[](0), new address[](0), new uint256[](0), new uint8[](0));
        uint256 end = offset + limit > n ? n : offset + limit;
        uint256 m = end - offset;
        ids = new uint256[](m);
        sellers = new address[](m);
        prices = new uint256[](m);
        rarities = new uint8[](m);
        for (uint256 i = 0; i < m; i++) {
            uint256 id = _listed[offset + i];
            Listing memory l = listingOf[id];
            (, uint8 rar) = cats.catOf(id);
            ids[i] = id;
            sellers[i] = l.seller;
            prices[i] = l.price;
            rarities[i] = rar;
        }
    }

    // ------------------------------------------------------------- internal

    /// @dev swap-and-pop из списка активных лотов
    function _remove(uint256 id) internal {
        delete listingOf[id];
        uint256 idx = _listedIdx[id];
        uint256 lastId = _listed[_listed.length - 1];
        _listed[idx] = lastId;
        _listedIdx[lastId] = idx;
        _listed.pop();
        delete _listedIdx[id];
    }
}

CatRenderer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title CatRenderer — метаданные и картинка котов прямо в блокчейне
/// @notice Отдаёт tokenURI как data:application/json;base64 с встроенной SVG.
///         Ни IPFS, ни сервера, ни отдельной загрузки 10 500 картинок:
///         кот рисуется из своей редкости и тикера в момент запроса.
///
/// @dev    Почему так, а не baseURI + id. Редкость и тикер решаются он-чейн
///         в момент минта (commit-reveal в боксе), поэтому заранее выложить
///         статические метаданные под каждый id невозможно — пришлось бы
///         держать сервер, который дорисовывает файл после каждой продажи.
///         Он-чейн рендер снимает эту зависимость целиком: маркетплейсы
///         увидят кота сразу после минта, даже если сайт лежит.
contract CatRenderer {
    string[5] private RARITY_NAME = ["Common", "Rare", "Epic", "Mythic", "Legendary"];
    // цвета совпадают с палитрой сайта
    string[5] private RARITY_COLOR = ["#8b93a7", "#4aa3e0", "#a06bff", "#e0559a", "#f5b544"];
    uint8[5]  private RARITY_MULT  = [1, 2, 3, 5, 8];

    /// @notice Полные метаданные кота: JSON с картинкой внутри.
    /// @dev    Сборка разнесена по мелким функциям: без via-ir длинные
    ///         abi.encodePacked не помещаются в стек, а весь проект
    ///         компилируется обычным путём (evmVersion paris, без via-ir).
    function tokenURI(uint256 id, string calldata ticker, uint8 rarity)
        external
        view
        returns (string memory)
    {
        require(rarity <= 4, "bad rarity");
        string memory image = _b64(bytes(_svg(id, ticker, RARITY_COLOR[rarity], RARITY_NAME[rarity])));
        return string(abi.encodePacked(
            "data:application/json;base64,",
            _b64(bytes(_json(id, ticker, rarity, image)))
        ));
    }

    function _json(uint256 id, string calldata ticker, uint8 rarity, string memory image)
        private
        view
        returns (string memory)
    {
        return string(abi.encodePacked(
            '{"name":"hood cat #', _toString(id),
            '","description":"Broker cat of the hood launchpad. Rarity sets the weight of treasury payouts in tokenized stocks; unclaimed dividends travel with the cat.',
            '","image":"data:image/svg+xml;base64,', image,
            '","attributes":[', _attrs(ticker, rarity), ']}'
        ));
    }

    function _attrs(string calldata ticker, uint8 rarity) private view returns (string memory) {
        return string(abi.encodePacked(
            '{"trait_type":"Rarity","value":"', RARITY_NAME[rarity], '"},',
            '{"trait_type":"Ticker","value":"', ticker, '"},',
            '{"trait_type":"Payout weight","value":', _toString(RARITY_MULT[rarity]), '}'
        ));
    }

    /// @dev Карточка кота: тёмный фон, рамка цвета редкости, пиксель-кот,
    ///      тикер и вес выплат. Всё в 400x400, без внешних ссылок.
    ///      Собирается по частям: один большой encodePacked не влезает в
    ///      стек без via-ir, а весь проект компилируется без него.
    function _svg(uint256 id, string calldata ticker, string memory color, string memory rname)
        private
        pure
        returns (string memory)
    {
        return string(abi.encodePacked(_head(color), _cat(color), _labels(id, ticker, color, rname)));
    }

    function _head(string memory color) private pure returns (string memory) {
        return string(abi.encodePacked(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400" width="400" height="400">',
            '<defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1">',
            '<stop offset="0" stop-color="', color, '" stop-opacity="0.28"/>',
            '<stop offset="1" stop-color="#0b0e14" stop-opacity="0"/></linearGradient></defs>',
            '<rect width="400" height="400" rx="28" fill="#0b0e14"/>',
            '<rect width="400" height="400" rx="28" fill="url(#g)"/>',
            '<rect x="6" y="6" width="388" height="388" rx="24" fill="none" stroke="', color, '" stroke-width="3"/>'
        ));
    }

    function _labels(uint256 id, string calldata ticker, string memory color, string memory rname)
        private
        pure
        returns (string memory)
    {
        return string(abi.encodePacked(_tickerText(ticker), _rarityText(color, rname), _idText(id)));
    }

    function _tickerText(string calldata ticker) private pure returns (string memory) {
        return string(abi.encodePacked(
            '<text x="200" y="300" font-family="monospace" font-size="34" font-weight="bold" fill="#ffffff" text-anchor="middle">$',
            ticker, '</text>'
        ));
    }

    function _rarityText(string memory color, string memory rname) private pure returns (string memory) {
        return string(abi.encodePacked(
            '<text x="200" y="332" font-family="monospace" font-size="18" fill="', color,
            '" text-anchor="middle">', rname, '</text>'
        ));
    }

    function _idText(uint256 id) private pure returns (string memory) {
        return string(abi.encodePacked(
            '<text x="200" y="364" font-family="monospace" font-size="14" fill="#8b93a7" text-anchor="middle">hood cat #',
            _toString(id), '</text></svg>'
        ));
    }

    /// @dev Пиксель-кот в цвете редкости — тот же силуэт, что на сайте.
    function _cat(string memory color) private pure returns (string memory) {
        return string(abi.encodePacked(
            // силуэт: уши, голова, тело. Масштаб 5 от сетки 32x32,
            // сдвиг подобран так, чтобы кот стоял по центру карточки
            '<g fill="', color, '" transform="translate(125,44) scale(5)">',
            '<rect x="1" y="1" width="4" height="5"/>',           // левое ухо
            '<rect x="13" y="1" width="4" height="5"/>',          // правое ухо
            '<rect x="1" y="5" width="16" height="12" rx="2"/>',  // голова
            '<rect x="5" y="17" width="8" height="9" rx="2"/>',   // тело
            '<rect x="3" y="26" width="3" height="3"/>',          // левая лапа
            '<rect x="12" y="26" width="3" height="3"/>',         // правая лапа
            '</g>',
            // морда: тёмные глаза и нос поверх головы (координаты в пикселях
            // холста, а не в сетке — так проще держать их на месте)
            '<g fill="#0b0e14">',
            '<rect x="150" y="98" width="14" height="14" rx="4"/>',  // левый глаз
            '<rect x="181" y="98" width="14" height="14" rx="4"/>',  // правый глаз
            '<rect x="166" y="120" width="13" height="7" rx="3"/>',  // нос
            '</g>'
        ));
    }

    // ------------------------------------------------------------- utils

    function _toString(uint256 v) private pure returns (string memory) {
        if (v == 0) return "0";
        uint256 digits;
        for (uint256 t = v; t != 0; t /= 10) digits++;
        bytes memory buf = new bytes(digits);
        while (v != 0) { buf[--digits] = bytes1(uint8(48 + v % 10)); v /= 10; }
        return string(buf);
    }

    bytes private constant B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    /// @dev Компактный base64: маркетплейсы ожидают data-URI именно в нём.
    function _b64(bytes memory data) private pure returns (string memory) {
        if (data.length == 0) return "";
        uint256 encLen = 4 * ((data.length + 2) / 3);
        bytes memory out = new bytes(encLen);
        bytes memory table = B64;
        uint256 i;
        uint256 j;
        for (; i + 3 <= data.length; i += 3) {
            uint256 n = (uint256(uint8(data[i])) << 16) | (uint256(uint8(data[i + 1])) << 8) | uint8(data[i + 2]);
            out[j++] = table[(n >> 18) & 63];
            out[j++] = table[(n >> 12) & 63];
            out[j++] = table[(n >> 6) & 63];
            out[j++] = table[n & 63];
        }
        if (data.length - i == 1) {
            uint256 n = uint256(uint8(data[i])) << 16;
            out[j++] = table[(n >> 18) & 63];
            out[j++] = table[(n >> 12) & 63];
            out[j++] = "=";
            out[j] = "=";
        } else if (data.length - i == 2) {
            uint256 n = (uint256(uint8(data[i])) << 16) | (uint256(uint8(data[i + 1])) << 8);
            out[j++] = table[(n >> 18) & 63];
            out[j++] = table[(n >> 12) & 63];
            out[j++] = table[(n >> 6) & 63];
            out[j] = "=";
        }
        return string(out);
    }
}

