// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IPoolV4 {
    function token() external view returns (address);
    function creator() external view returns (address);
    function quote() external view returns (address);
    function claimProtocolFees() external;
}

interface IFactoryV4 {
    function poolOf(address token) external view returns (address);
}

interface IAgentTreasuryV4 {
    function fund(address token) external payable;
    function fundErc20(address token, address asset, uint256 amount) external;
}

/// @title FeeSplitterV4
/// @notice Протокольная доля комиссии каждой сделки делится здесь, а не в
///         пуле. Ставится казной обеих фабрик (ETH и за валюту), пулы не
///         меняются: они по-прежнему шлют протокольную долю на один адрес.
///
///         Экономика (решение владельца 14.09.2026), при creatorFeeShareBps
///         = 7000 в пуле сюда приходит 30% комиссии:
///
///             монета с ИИ:  создатель 70% · команда 20% · агент монеты 10%
///             монета без:   создатель 80% · команда 20%
///
///         Есть ли у монеты ИИ — решает её создатель, один раз и навсегда:
///         `enableAi(token)`. Включить можно позже, выключить — нельзя,
///         иначе включали бы ради витрины и тут же забирали 10% обратно.
///         Пока флаг не поставлен, лишние 10% уходят создателю.
///
///         Старые монеты с creatorFeeShareBps = 5000 присылают сюда 50%:
///         пропорция та же — команде 2/3 входящего, треть агенту/создателю.
///
///         ETH-пулы платят пушем (`claimProtocolFees` шлёт ETH с самого пула,
///         msg.sender здесь — пул). Пулы за валюту платят ERC20-переводом,
///         без колбэка, поэтому для них `claim(pool)`: сплиттер сам дёргает
///         выплату и считает, сколько именно этот пул прислал — так USDG
///         десяти разных монет не смешиваются.
///
///         Ни у кого нет права что-то здесь менять: ни адресов, ни долей.
///         Создателю, чей кошелёк не принимает перевод, сумма откладывается
///         и забирается `withdraw*` — выплата комиссий из-за него не встаёт.
contract FeeSplitterV4 is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public immutable team;
    IAgentTreasuryV4 public immutable agentTreasury;
    IFactoryV4 public immutable ethFactory;   // address(0) — ETH-фабрики нет
    IFactoryV4 public immutable quoteFactory; // address(0) — фабрики за валюту нет

    /// @notice Доля команды от ВХОДЯЩЕГО: teamNum/teamDen. 2/3 при 30% => 20%.
    uint256 public immutable teamNum;
    uint256 public immutable teamDen;

    /// @notice У монеты включён ИИ (решение создателя, необратимо).
    mapping(address => bool) public aiOf;

    /// @notice Отложенные суммы для создателей, чьи кошельки не приняли перевод.
    mapping(address => uint256) public pendingEth;
    mapping(address => mapping(address => uint256)) public pendingErc20; // кому => валюта => сумма
    mapping(address => uint256) public totalPendingErc20;                // валюта => сумма (для sweep)

    uint256 private constant PUSH_GAS = 60_000;

    event AiEnabled(address indexed token, address indexed creator);
    event SplitEth(address indexed token, uint256 toTeam, uint256 toAgent, uint256 toCreator);
    event SplitErc20(address indexed token, address indexed asset, uint256 toTeam, uint256 toAgent, uint256 toCreator);
    event Deferred(address indexed to, address indexed asset, uint256 amount);
    event Withdrawn(address indexed to, address indexed asset, uint256 amount);
    event Swept(address indexed asset, uint256 amount);

    constructor(
        address team_,
        address agentTreasury_,
        address ethFactory_,
        address quoteFactory_,
        uint256 teamNum_,
        uint256 teamDen_
    ) {
        require(team_ != address(0) && agentTreasury_ != address(0), "zero addr");
        require(ethFactory_ != address(0) || quoteFactory_ != address(0), "no factory");
        require(teamDen_ > 0 && teamNum_ <= teamDen_, "bad share");
        team = team_;
        agentTreasury = IAgentTreasuryV4(agentTreasury_);
        ethFactory = IFactoryV4(ethFactory_);
        quoteFactory = IFactoryV4(quoteFactory_);
        teamNum = teamNum_;
        teamDen = teamDen_;
    }

    // ------------------------------------------------------------ реестр ИИ

    /// @notice Создатель включает ИИ своей монете. Навсегда.
    function enableAi(address token) external {
        address pool = poolOf(token);
        require(pool != address(0), "unknown token");
        require(IPoolV4(pool).creator() == msg.sender, "not creator");
        require(!aiOf[token], "already on");
        aiOf[token] = true;
        emit AiEnabled(token, msg.sender);
    }

    /// @notice Пул монеты в любой из фабрик; address(0) — монета не наша.
    function poolOf(address token) public view returns (address pool) {
        if (address(ethFactory) != address(0)) {
            pool = ethFactory.poolOf(token);
            if (pool != address(0)) return pool;
        }
        if (address(quoteFactory) != address(0)) pool = quoteFactory.poolOf(token);
    }

    /// @notice Сколько от входящего достаётся команде, в bps — для сайта.
    function teamShareBps() external view returns (uint256) {
        return (teamNum * 10_000) / teamDen;
    }

    // ---------------------------------------------------------- ETH-пулы

    /// @dev `claimProtocolFees()` ETH-пула шлёт сюда со всем газом. Не пул
    ///      (пожертвование, случайный перевод) — всё команде, без реверта.
    receive() external payable nonReentrant {
        (address token, address creator) = _resolveEthPool(msg.sender);
        _splitEth(token, creator, msg.value);
    }

    function _resolveEthPool(address pool) internal view returns (address token, address creator) {
        if (address(ethFactory) == address(0)) return (address(0), address(0));
        try IPoolV4(pool).token() returns (address t) { token = t; } catch { return (address(0), address(0)); }
        if (token == address(0) || ethFactory.poolOf(token) != pool) return (address(0), address(0));
        try IPoolV4(pool).creator() returns (address c) { creator = c; } catch { creator = address(0); }
    }

    function _splitEth(address token, address creator, uint256 amount) internal {
        if (amount == 0) return;
        if (token == address(0)) {
            _sendEth(team, amount);
            emit SplitEth(address(0), amount, 0, 0);
            return;
        }
        uint256 toTeam = (amount * teamNum) / teamDen;
        uint256 rest = amount - toTeam;
        uint256 toAgent;
        uint256 toCreator;

        if (rest > 0) {
            if (aiOf[token]) {
                // Сломанная казна агента не должна останавливать выплату
                // комиссий — тогда её доля уходит команде.
                try agentTreasury.fund{value: rest}(token) { toAgent = rest; }
                catch { toTeam += rest; }
            } else if (creator != address(0)) {
                toCreator = rest;
                if (!_tryEth(creator, rest)) {
                    pendingEth[creator] += rest;
                    emit Deferred(creator, address(0), rest);
                }
            } else {
                toTeam += rest;
            }
        }
        _sendEth(team, toTeam);
        emit SplitEth(token, toTeam, toAgent, toCreator);
    }

    // ------------------------------------------------------- пулы за валюту

    /// @notice Забрать протокольную долю у пула за валюту и поделить её.
    ///         Зовёт кто угодно (казначей по расписанию, сам создатель).
    function claim(address pool) external nonReentrant {
        require(address(quoteFactory) != address(0), "no quote factory");
        address token = IPoolV4(pool).token();
        require(token != address(0) && quoteFactory.poolOf(token) == pool, "not a pool");
        IERC20 asset = IERC20(IPoolV4(pool).quote());

        uint256 before = asset.balanceOf(address(this));
        IPoolV4(pool).claimProtocolFees();
        uint256 got = asset.balanceOf(address(this)) - before;
        if (got == 0) return;

        address creator = IPoolV4(pool).creator();
        uint256 toTeam = (got * teamNum) / teamDen;
        uint256 rest = got - toTeam;
        uint256 toAgent;
        uint256 toCreator;

        if (rest > 0) {
            if (aiOf[token]) {
                asset.forceApprove(address(agentTreasury), rest);
                try agentTreasury.fundErc20(token, address(asset), rest) { toAgent = rest; }
                catch { toTeam += rest; }
                asset.forceApprove(address(agentTreasury), 0);
            } else if (creator != address(0)) {
                toCreator = rest;
                if (!_tryErc20(asset, creator, rest)) {
                    pendingErc20[creator][address(asset)] += rest;
                    totalPendingErc20[address(asset)] += rest;
                    emit Deferred(creator, address(asset), rest);
                }
            } else {
                toTeam += rest;
            }
        }
        if (toTeam > 0) asset.safeTransfer(team, toTeam);
        emit SplitErc20(token, address(asset), toTeam, toAgent, toCreator);
    }

    // ------------------------------------------------------- отложенное

    function withdrawEth() external nonReentrant {
        uint256 amount = pendingEth[msg.sender];
        require(amount > 0, "nothing");
        pendingEth[msg.sender] = 0;
        _sendEth(msg.sender, amount);
        emit Withdrawn(msg.sender, address(0), amount);
    }

    function withdrawErc20(address asset) external nonReentrant {
        uint256 amount = pendingErc20[msg.sender][asset];
        require(amount > 0, "nothing");
        pendingErc20[msg.sender][asset] = 0;
        totalPendingErc20[asset] -= amount;
        IERC20(asset).safeTransfer(msg.sender, amount);
        emit Withdrawn(msg.sender, asset, amount);
    }

    /// @notice Валюта, попавшая сюда мимо пулов (прямой перевод), — команде.
    ///         Отложенные суммы создателей не трогаются.
    function sweep(address asset) external nonReentrant {
        uint256 free = IERC20(asset).balanceOf(address(this)) - totalPendingErc20[asset];
        require(free > 0, "nothing");
        IERC20(asset).safeTransfer(team, free);
        emit Swept(asset, free);
    }

    // ------------------------------------------------------------ helpers

    function _sendEth(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "ETH send failed");
    }

    /// @dev Пуш с ограниченным газом: контракт-получатель не может ни
    ///      сжечь весь газ выплаты, ни уронить её реверт-ом.
    function _tryEth(address to, uint256 amount) internal returns (bool ok) {
        (ok, ) = to.call{value: amount, gas: PUSH_GAS}("");
    }

    /// @dev transfer без реверта: и «нет return», и «false», и revert
    ///      одинаково значат «не дошло» — тогда сумма откладывается.
    function _tryErc20(IERC20 asset, address to, uint256 amount) internal returns (bool) {
        (bool ok, bytes memory data) = address(asset).call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, amount)
        );
        return ok && (data.length == 0 || abi.decode(data, (bool)));
    }
}

FeeSplitterV5.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IPoolV5 {
    function token() external view returns (address);
    function creator() external view returns (address);
    function quote() external view returns (address);
    function claimProtocolFees() external;
}

interface IFactoryV5 {
    function poolOf(address token) external view returns (address);
}

interface IPrevSplitterV5 {
    function aiOf(address token) external view returns (bool);
}

interface IAgentTreasuryV5 {
    function fund(address token) external payable;
    function fundErc20(address token, address asset, uint256 amount) external;
}

/// @title FeeSplitterV5
/// @notice Протокольная доля комиссии каждой сделки делится здесь, а не в
///         пуле. Ставится казной обеих фабрик (ETH и за валюту), пулы не
///         меняются: они по-прежнему шлют протокольную долю на один адрес.
///
///         Экономика (решение владельца 15.09.2026), при creatorFeeShareBps
///         = 6000 в пуле сюда приходит 40% комиссии:
///
///             монета без ИИ: создатель 70% · арена 20% · команда 10%
///             монета с ИИ:   создатель 60% · арена 20% · команда 10% · агент монеты 10%
///
///         Пул отдаёт создателю 60% сразу; из 40% здесь: половина — казне
///         арены (ежедневный выкуп и сжигание подиума), четверть — команде,
///         четверть — агенту монеты (если создатель включил ИИ: enableAi)
///         или обратно создателю. Доли заданы дробями arenaNum/den и
///         teamNum/den при деплое и неизменяемы.
///
///         Старые монеты присылают сюда свою долю (30% при 7000, 50% при
///         5000) — пропорция та же: половина арене, по четверти команде и
///         агенту/создателю.
///
///         Есть ли у монеты ИИ — решает её создатель, один раз и навсегда:
///         `enableAi(token)`. Включить можно позже, выключить — нельзя.
///
///         ETH-пулы платят пушем (`claimProtocolFees` шлёт ETH с самого пула,
///         msg.sender здесь — пул). Пулы за валюту платят ERC20-переводом,
///         без колбэка, поэтому для них `claim(pool)`.
///
///         Ни у кого нет права что-то здесь менять: ни адресов, ни долей.
///         Казна арены, не принявшая ETH (не должно случаться), не
///         останавливает выплату: её доля уходит команде. Создателю, чей
///         кошелёк не принимает перевод, сумма откладывается (`withdraw*`).
contract FeeSplitterV5 is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public immutable team;
    /// @notice Казна арены: сюда уходит доля арены (ETH и валюта).
    address public immutable arena;
    IAgentTreasuryV5 public immutable agentTreasury;
    IFactoryV5 public immutable ethFactory;   // address(0) — ETH-фабрики нет
    IFactoryV5 public immutable quoteFactory; // address(0) — фабрики за валюту нет

    /// @notice Доли от ВХОДЯЩЕГО: арене arenaNum/den, команде teamNum/den,
    ///         остаток — агенту монеты или создателю. При 40% входящего и
    ///         долях 2/4 и 1/4 это 20% / 10% / 10% от комиссии.
    uint256 public immutable arenaNum;
    uint256 public immutable teamNum;
    uint256 public immutable den;

    /// @notice Прежний сплиттер (V4): включённый там ИИ действует и здесь —
    ///         создателям не нужно подписывать включение заново. address(0) — нет.
    IPrevSplitterV5 public immutable prev;

    /// @notice У монеты включён ИИ (решение создателя, необратимо) — здесь.
    mapping(address => bool) private _ai;

    /// @notice Отложенные суммы для создателей, чьи кошельки не приняли перевод.
    mapping(address => uint256) public pendingEth;
    mapping(address => mapping(address => uint256)) public pendingErc20; // кому => валюта => сумма
    mapping(address => uint256) public totalPendingErc20;                // валюта => сумма (для sweep)

    uint256 private constant PUSH_GAS = 60_000;

    event AiEnabled(address indexed token, address indexed creator);
    event SplitEth(address indexed token, uint256 toArena, uint256 toTeam, uint256 toAgent, uint256 toCreator);
    event SplitErc20(address indexed token, address indexed asset, uint256 toArena, uint256 toTeam, uint256 toAgent, uint256 toCreator);
    event Deferred(address indexed to, address indexed asset, uint256 amount);
    event Withdrawn(address indexed to, address indexed asset, uint256 amount);
    event Swept(address indexed asset, uint256 amount);

    constructor(
        address team_,
        address arena_,
        address agentTreasury_,
        address ethFactory_,
        address quoteFactory_,
        address prev_,
        uint256 arenaNum_,
        uint256 teamNum_,
        uint256 den_
    ) {
        require(team_ != address(0) && arena_ != address(0) && agentTreasury_ != address(0), "zero addr");
        require(ethFactory_ != address(0) || quoteFactory_ != address(0), "no factory");
        require(den_ > 0 && arenaNum_ + teamNum_ <= den_, "bad share");
        team = team_;
        arena = arena_;
        agentTreasury = IAgentTreasuryV5(agentTreasury_);
        ethFactory = IFactoryV5(ethFactory_);
        quoteFactory = IFactoryV5(quoteFactory_);
        prev = IPrevSplitterV5(prev_);
        arenaNum = arenaNum_;
        teamNum = teamNum_;
        den = den_;
    }

    // ------------------------------------------------------------ реестр ИИ

    /// @notice У монеты включён ИИ: здесь или ещё в прежнем сплиттере.
    function aiOf(address token) public view returns (bool) {
        if (_ai[token]) return true;
        if (address(prev) == address(0)) return false;
        try prev.aiOf(token) returns (bool on) { return on; } catch { return false; }
    }

    /// @notice Создатель включает ИИ своей монете. Навсегда.
    function enableAi(address token) external {
        address pool = poolOf(token);
        require(pool != address(0), "unknown token");
        require(IPoolV5(pool).creator() == msg.sender, "not creator");
        require(!aiOf(token), "already on");
        _ai[token] = true;
        emit AiEnabled(token, msg.sender);
    }

    /// @notice Пул монеты в любой из фабрик; address(0) — монета не наша.
    function poolOf(address token) public view returns (address pool) {
        if (address(ethFactory) != address(0)) {
            pool = ethFactory.poolOf(token);
            if (pool != address(0)) return pool;
        }
        if (address(quoteFactory) != address(0)) pool = quoteFactory.poolOf(token);
    }

    /// @notice Сколько от входящего достаётся команде, в bps — для сайта.
    function teamShareBps() external view returns (uint256) {
        return (teamNum * 10_000) / den;
    }

    /// @notice Сколько от входящего достаётся арене, в bps — для сайта.
    function arenaShareBps() external view returns (uint256) {
        return (arenaNum * 10_000) / den;
    }

    // ---------------------------------------------------------- ETH-пулы

    /// @dev `claimProtocolFees()` ETH-пула шлёт сюда со всем газом. Не пул
    ///      (пожертвование, случайный перевод) — всё команде, без реверта.
    receive() external payable nonReentrant {
        (address token, address creator) = _resolveEthPool(msg.sender);
        _splitEth(token, creator, msg.value);
    }

    function _resolveEthPool(address pool) internal view returns (address token, address creator) {
        if (address(ethFactory) == address(0)) return (address(0), address(0));
        try IPoolV5(pool).token() returns (address t) { token = t; } catch { return (address(0), address(0)); }
        if (token == address(0) || ethFactory.poolOf(token) != pool) return (address(0), address(0));
        try IPoolV5(pool).creator() returns (address c) { creator = c; } catch { creator = address(0); }
    }

    function _splitEth(address token, address creator, uint256 amount) internal {
        if (amount == 0) return;
        if (token == address(0)) {
            _sendEth(team, amount);
            emit SplitEth(address(0), 0, amount, 0, 0);
            return;
        }
        uint256 toArena = (amount * arenaNum) / den;
        uint256 toTeam = (amount * teamNum) / den;
        uint256 rest = amount - toArena - toTeam;
        uint256 toAgent;
        uint256 toCreator;

        // Казна арены — контракт с простым receive(); не приняла — команде,
        // выплата комиссий из-за этого не встаёт.
        if (toArena > 0 && !_tryEth(arena, toArena)) {
            toTeam += toArena;
            toArena = 0;
        }

        if (rest > 0) {
            if (aiOf(token)) {
                // Сломанная казна агента не должна останавливать выплату
                // комиссий — тогда её доля уходит команде.
                try agentTreasury.fund{value: rest}(token) { toAgent = rest; }
                catch { toTeam += rest; }
            } else if (creator != address(0)) {
                toCreator = rest;
                if (!_tryEth(creator, rest)) {
                    pendingEth[creator] += rest;
                    emit Deferred(creator, address(0), rest);
                }
            } else {
                toTeam += rest;
            }
        }
        _sendEth(team, toTeam);
        emit SplitEth(token, toArena, toTeam, toAgent, toCreator);
    }

    // ------------------------------------------------------- пулы за валюту

    /// @notice Забрать протокольную долю у пула за валюту и поделить её.
    ///         Зовёт кто угодно (казначей по расписанию, сам создатель).
    function claim(address pool) external nonReentrant {
        require(address(quoteFactory) != address(0), "no quote factory");
        address token = IPoolV5(pool).token();
        require(token != address(0) && quoteFactory.poolOf(token) == pool, "not a pool");
        IERC20 asset = IERC20(IPoolV5(pool).quote());

        uint256 before = asset.balanceOf(address(this));
        IPoolV5(pool).claimProtocolFees();
        uint256 got = asset.balanceOf(address(this)) - before;
        if (got == 0) return;

        address creator = IPoolV5(pool).creator();
        uint256 toArena = (got * arenaNum) / den;
        uint256 toTeam = (got * teamNum) / den;
        uint256 rest = got - toArena - toTeam;
        uint256 toAgent;
        uint256 toCreator;

        if (rest > 0) {
            if (aiOf(token)) {
                asset.forceApprove(address(agentTreasury), rest);
                try agentTreasury.fundErc20(token, address(asset), rest) { toAgent = rest; }
                catch { toTeam += rest; }
                asset.forceApprove(address(agentTreasury), 0);
            } else if (creator != address(0)) {
                toCreator = rest;
                if (!_tryErc20(asset, creator, rest)) {
                    pendingErc20[creator][address(asset)] += rest;
                    totalPendingErc20[address(asset)] += rest;
                    emit Deferred(creator, address(asset), rest);
                }
            } else {
                toTeam += rest;
            }
        }
        if (toArena > 0) asset.safeTransfer(arena, toArena);
        if (toTeam > 0) asset.safeTransfer(team, toTeam);
        emit SplitErc20(token, address(asset), toArena, toTeam, toAgent, toCreator);
    }

    // ------------------------------------------------------- отложенное

    function withdrawEth() external nonReentrant {
        uint256 amount = pendingEth[msg.sender];
        require(amount > 0, "nothing");
        pendingEth[msg.sender] = 0;
        _sendEth(msg.sender, amount);
        emit Withdrawn(msg.sender, address(0), amount);
    }

    function withdrawErc20(address asset) external nonReentrant {
        uint256 amount = pendingErc20[msg.sender][asset];
        require(amount > 0, "nothing");
        pendingErc20[msg.sender][asset] = 0;
        totalPendingErc20[asset] -= amount;
        IERC20(asset).safeTransfer(msg.sender, amount);
        emit Withdrawn(msg.sender, asset, amount);
    }

    /// @notice Валюта, попавшая сюда мимо пулов (прямой перевод), — команде.
    ///         Отложенные суммы создателей не трогаются.
    function sweep(address asset) external nonReentrant {
        uint256 free = IERC20(asset).balanceOf(address(this)) - totalPendingErc20[asset];
        require(free > 0, "nothing");
        IERC20(asset).safeTransfer(team, free);
        emit Swept(asset, free);
    }

    // ------------------------------------------------------------ helpers

    function _sendEth(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "ETH send failed");
    }

    /// @dev Пуш с ограниченным газом: контракт-получатель не может ни
    ///      сжечь весь газ выплаты, ни уронить её реверт-ом.
    function _tryEth(address to, uint256 amount) internal returns (bool ok) {
        (ok, ) = to.call{value: amount, gas: PUSH_GAS}("");
    }

    /// @dev transfer без реверта: и «нет return», и «false», и revert
    ///      одинаково значат «не дошло» — тогда сумма откладывается.
    function _tryErc20(IERC20 asset, address to, uint256 amount) internal returns (bool) {
        (bool ok, bytes memory data) = address(asset).call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, amount)
        );
        return ok && (data.length == 0 || abi.decode(data, (bool)));
    }
}

FeeSplitterV6.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IPoolV6 {
    function token() external view returns (address);
    function quote() external view returns (address);
    function claimProtocolFees() external;
}

interface IFactoryV6 {
    function poolOf(address token) external view returns (address);
}

/// @title FeeSplitterV6 — делёж комиссий платформы (перезапуск 09.2026)
/// @notice Комиссия сделки 1%. Пул сразу отдаёт создателю его долю
///         (creatorFeeShareBps = 7000 → 70%), остаток (30%) приходит сюда и
///         делится на три казны в пропорции, заданной при деплое:
///
///             создатель 70% · арена 10% · выкуп монеты hood 10% · команда 10%
///
///         Здесь это arenaNum/den → казна арены (ежедневный выкуп-сжигание
///         подиума), buybackNum/den → казна выкупа монеты hood, остальное —
///         команде. ИИ-агентов в этой версии нет.
///
///         ETH-пулы платят пушем (`claimProtocolFees` шлёт ETH с самого пула,
///         msg.sender здесь — пул). Пулы за валюту платят ERC20-переводом
///         без колбэка, поэтому для них `claim(pool)` — может звать любой.
///
///         Ни у кого нет права что-то здесь менять: ни адресов, ни долей.
///         Казна, не принявшая ETH (не должно случаться), не останавливает
///         выплату: её доля уходит команде.
contract FeeSplitterV6 is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public immutable team;
    address public immutable arena;
    address public immutable buyback;
    IFactoryV6 public immutable ethFactory;
    IFactoryV6 public immutable quoteFactory;

    uint256 public immutable arenaNum;
    uint256 public immutable buybackNum;
    uint256 public immutable den;

    /// @dev Газ на пуш ETH контракту-казне: хватает на receive() с записью
    ///      пары слотов, но не даёт получателю сжечь газ выплаты.
    uint256 internal constant PUSH_GAS = 60_000;

    event SplitEth(address indexed token, uint256 toArena, uint256 toBuyback, uint256 toTeam);
    event SplitErc20(address indexed token, address indexed asset, uint256 toArena, uint256 toBuyback, uint256 toTeam);
    event Swept(address indexed asset, uint256 amount);

    constructor(
        address team_,
        address arena_,
        address buyback_,
        address ethFactory_,
        address quoteFactory_,
        uint256 arenaNum_,
        uint256 buybackNum_,
        uint256 den_
    ) {
        require(team_ != address(0) && arena_ != address(0) && buyback_ != address(0), "zero addr");
        require(ethFactory_ != address(0) || quoteFactory_ != address(0), "no factory");
        require(den_ > 0 && arenaNum_ + buybackNum_ <= den_, "bad share");
        team = team_;
        arena = arena_;
        buyback = buyback_;
        ethFactory = IFactoryV6(ethFactory_);
        quoteFactory = IFactoryV6(quoteFactory_);
        arenaNum = arenaNum_;
        buybackNum = buybackNum_;
        den = den_;
    }

    // ------------------------------------------------------------- views

    /// @notice Пул монеты в любой из фабрик; address(0) — монета не наша.
    function poolOf(address token) public view returns (address pool) {
        if (address(ethFactory) != address(0)) {
            pool = ethFactory.poolOf(token);
            if (pool != address(0)) return pool;
        }
        if (address(quoteFactory) != address(0)) pool = quoteFactory.poolOf(token);
    }

    /// @notice Доля команды от входящего, bps — для сайта.
    function teamShareBps() external view returns (uint256) {
        return ((den - arenaNum - buybackNum) * 10_000) / den;
    }

    /// @notice Доля казны арены от входящего, bps.
    function arenaShareBps() external view returns (uint256) {
        return (arenaNum * 10_000) / den;
    }

    /// @notice Доля казны выкупа hood от входящего, bps.
    function buybackShareBps() external view returns (uint256) {
        return (buybackNum * 10_000) / den;
    }

    // ---------------------------------------------------------- ETH-пулы

    /// @dev `claimProtocolFees()` ETH-пула шлёт сюда со всем газом. Не пул
    ///      (пожертвование, случайный перевод) — всё команде, без реверта.
    receive() external payable nonReentrant {
        address token = _resolveEthPool(msg.sender);
        _splitEth(token, msg.value);
    }

    function _resolveEthPool(address pool) internal view returns (address token) {
        if (address(ethFactory) == address(0) || pool.code.length == 0) return address(0);
        try IPoolV6(pool).token() returns (address t) { token = t; } catch { return address(0); }
        if (token == address(0) || ethFactory.poolOf(token) != pool) return address(0);
    }

    function _splitEth(address token, uint256 amount) internal {
        if (amount == 0) return;
        if (token == address(0)) {
            _sendEth(team, amount);
            emit SplitEth(address(0), 0, 0, amount);
            return;
        }
        uint256 toArena = (amount * arenaNum) / den;
        uint256 toBuyback = (amount * buybackNum) / den;
        uint256 toTeam = amount - toArena - toBuyback;

        // Казны — контракты с простым receive(); не приняла — команде,
        // выплата комиссий из-за этого не встаёт.
        if (toArena > 0 && !_tryEth(arena, toArena)) { toTeam += toArena; toArena = 0; }
        if (toBuyback > 0 && !_tryEth(buyback, toBuyback)) { toTeam += toBuyback; toBuyback = 0; }

        _sendEth(team, toTeam);
        emit SplitEth(token, toArena, toBuyback, toTeam);
    }

    // ------------------------------------------------------ пулы за валюту

    /// @notice Забрать комиссии пула за валюту и разделить. Звать может кто
    ///         угодно: деньги идут только по зашитым адресам.
    function claim(address pool) external nonReentrant {
        address token = IPoolV6(pool).token();
        require(token != address(0) && address(quoteFactory) != address(0)
            && quoteFactory.poolOf(token) == pool, "not our pool");
        IERC20 asset = IERC20(IPoolV6(pool).quote());

        uint256 before = asset.balanceOf(address(this));
        IPoolV6(pool).claimProtocolFees();
        uint256 got = asset.balanceOf(address(this)) - before;
        if (got == 0) return;

        uint256 toArena = (got * arenaNum) / den;
        uint256 toBuyback = (got * buybackNum) / den;
        uint256 toTeam = got - toArena - toBuyback;
        if (toArena > 0) asset.safeTransfer(arena, toArena);
        if (toBuyback > 0) asset.safeTransfer(buyback, toBuyback);
        if (toTeam > 0) asset.safeTransfer(team, toTeam);
        emit SplitErc20(token, address(asset), toArena, toBuyback, toTeam);
    }

    /// @notice Валюта, попавшая сюда мимо пулов (прямой перевод), — команде.
    function sweep(address asset) external nonReentrant {
        uint256 free = IERC20(asset).balanceOf(address(this));
        require(free > 0, "nothing");
        IERC20(asset).safeTransfer(team, free);
        emit Swept(asset, free);
    }

    // ------------------------------------------------------------ helpers

    function _sendEth(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "ETH send failed");
    }

    /// @dev Пуш с ограниченным газом: контракт-получатель не может ни
    ///      сжечь весь газ выплаты, ни уронить её реверт-ом.
    function _tryEth(address to, uint256 amount) internal returns (bool ok) {
        (ok, ) = to.call{value: amount, gas: PUSH_GAS}("");
    }
}

HoodChat.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title HoodChat
/// @notice Fully on-chain chat for hood tokens. A message is just an event:
///         no storage, no moderation keys, no backend — anyone can post,
///         authorship is proven by the sender's signature, history lives
///         in the chain forever. Reading is free (event logs).
contract HoodChat {
    event Message(
        address indexed token,
        address indexed sender,
        string text,
        uint256 timestamp
    );

    error BadLength();

    /// @param token the token this message belongs to (its chat room)
    /// @param text  1..280 bytes
    function post(address token, string calldata text) external {
        uint256 len = bytes(text).length;
        if (len == 0 || len > 280) revert BadLength();
        emit Message(token, msg.sender, text, block.timestamp);
    }
}

HoodTaxToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/// @title HoodTaxToken — tax-токен hood (v1, аналог flap tax token)
/// @notice ERC20 с налогом на сделки через отмеченные пулы (курва/AMM):
///         покупка и продажа облагаются раздельными ставками (до 10%).
///         Собранный налог делится по зашитой при деплое аллокации:
///           • mktBps  — кошельку создателя (дев/маркетинг), сразу;
///           • burnBps — сжигается, сразу (дефляция);
///           • divBps  — дивиденды холдерам в самом токене (клейм);
///           • lpBps   — копится на контракте под ликвидность, flushLp()
///                       отправляет накопленное в lpSink (казна/локер).
///         Право на дивиденды: баланс >= minShare и адрес не исключён.
///         Аллокация и ставки неизменяемы. Controller (фабрика) может только
///         отмечать пулы и отказаться от роли (renounce) — никаких минтов,
///         пауз и чёрных списков.
/// @dev    Дивиденды — классический magnified-per-share, но поверх «теневого»
///         дивидендного баланса: divBalance = balance, если адрес имеет право,
///         иначе 0. Это даёт честный учёт порога minShare без циклов по холдерам.
contract HoodTaxToken is ERC20 {
    uint256 private constant MAG = 2 ** 128;
    uint16 public constant BPS = 10_000;
    uint16 public constant MAX_TAX_BPS = 1_000; // 10%

    struct TaxConfig {
        uint16 buyTaxBps;
        uint16 sellTaxBps;
        uint16 mktBps;   // доля налога кошельку создателя
        uint16 burnBps;  // доля налога на сжигание
        uint16 divBps;   // доля налога в дивиденды
        uint16 lpBps;    // доля налога в ликвидность
        uint256 minShare; // мин. баланс для права на дивиденды
    }

    uint16 public immutable buyTaxBps;
    uint16 public immutable sellTaxBps;
    uint16 public immutable mktBps;
    uint16 public immutable burnBps;
    uint16 public immutable divBps;
    uint16 public immutable lpBps;
    uint256 public immutable minShare;

    address public immutable creatorWallet;
    address public immutable lpSink;
    address public controller; // фабрика; может отметить пулы и отречься

    string public metadataURI;

    mapping(address => bool) public taxedPools;  // курва + AMM-пулы
    mapping(address => bool) public taxExempt;   // не платят налог (инфраструктура)

    // --- дивиденды (в самом токене) поверх теневого баланса
    uint256 public magnifiedDividendPerShare;
    uint256 public divSupply;                    // сумма теневых балансов
    uint256 public lpReserve;                    // токены, накопленные под ликвидность
    mapping(address => uint256) public divBalance;
    mapping(address => int256) private corrections;
    mapping(address => uint256) public withdrawn;

    bool private _inTax; // защита от рекурсии внутренних переводов налога

    event PoolSet(address indexed pool, bool taxed);
    event TaxTaken(address indexed payer, uint256 amount, bool isBuy);
    event DividendsDistributed(uint256 amount);
    event DividendClaimed(address indexed holder, uint256 amount);
    event LpFlushed(uint256 amount);
    event ControllerRenounced();

    modifier onlyController() {
        require(msg.sender == controller, "not controller");
        _;
    }

    constructor(
        string memory name_,
        string memory symbol_,
        string memory metadataURI_,
        address mintTo,
        uint256 totalSupply_,
        address creatorWallet_,
        address lpSink_,
        TaxConfig memory cfg
    ) ERC20(name_, symbol_) {
        require(cfg.buyTaxBps <= MAX_TAX_BPS && cfg.sellTaxBps <= MAX_TAX_BPS, "tax > 10%");
        require(cfg.mktBps + cfg.burnBps + cfg.divBps + cfg.lpBps == BPS, "alloc != 100%");
        require(creatorWallet_ != address(0) && lpSink_ != address(0), "zero addr");

        metadataURI = metadataURI_;
        buyTaxBps = cfg.buyTaxBps;
        sellTaxBps = cfg.sellTaxBps;
        mktBps = cfg.mktBps;
        burnBps = cfg.burnBps;
        divBps = cfg.divBps;
        lpBps = cfg.lpBps;
        minShare = cfg.minShare;
        creatorWallet = creatorWallet_;
        lpSink = lpSink_;
        controller = msg.sender;

        // инфраструктура не платит налог и не участвует в дивидендах
        taxExempt[address(this)] = true;
        taxExempt[creatorWallet_] = true;
        taxExempt[lpSink_] = true;
        taxExempt[msg.sender] = true;

        _mint(mintTo, totalSupply_);
    }

    // ---------------------------------------------------------------- admin

    function setPool(address pool, bool taxed) external onlyController {
        require(pool != address(0), "zero pool");
        taxedPools[pool] = taxed;
        _refreshDivBalance(pool);
        emit PoolSet(pool, taxed);
    }

    function renounceController() external onlyController {
        controller = address(0);
        emit ControllerRenounced();
    }

    // ---------------------------------------------------------------- tax core

    function _update(address from, address to, uint256 value) internal override {
        // внутренние переводы налога и mint/burn — без повторного налога
        if (_inTax || from == address(0) || to == address(0)) {
            super._update(from, to, value);
            _afterMove(from, to);
            return;
        }

        bool isBuy = taxedPools[from];
        bool isSell = taxedPools[to];
        bool exempt = taxExempt[from] || taxExempt[to];

        if ((isBuy || isSell) && !exempt) {
            uint16 rate = isBuy ? buyTaxBps : sellTaxBps;
            uint256 fee = (value * rate) / BPS;
            if (fee > 0) {
                _inTax = true;
                super._update(from, to, value - fee);
                super._update(from, address(this), fee);
                // регистрируем участников ДО раздачи: покупатель этой же сделки
                // участвует в дивидендах с её налога (если проходит порог)
                _afterMove(from, to);

                uint256 toBurn = (fee * burnBps) / BPS;
                uint256 toMkt = (fee * mktBps) / BPS;
                uint256 toDiv = (fee * divBps) / BPS;
                // остаток (включая пыль округления) — в ликвидность
                uint256 toLp = fee - toBurn - toMkt - toDiv;

                if (toBurn > 0) _burn(address(this), toBurn);
                if (toMkt > 0) super._update(address(this), creatorWallet, toMkt);
                if (toDiv > 0) _distribute(toDiv);
                lpReserve += toLp;
                _inTax = false;

                emit TaxTaken(isBuy ? to : from, fee, isBuy);
                return; // _afterMove уже выполнен выше
            }
        }

        super._update(from, to, value);
        _afterMove(from, to);
    }

    /// @dev Дивидендная доля налога: если есть кому раздавать — увеличиваем
    ///      счётчик на акцию; если правомочных холдеров нет — в ликвидность.
    function _distribute(uint256 amount) private {
        if (divSupply == 0) {
            lpReserve += amount;
            return;
        }
        magnifiedDividendPerShare += (amount * MAG) / divSupply;
        emit DividendsDistributed(amount);
    }

    // ---------------------------------------------------------------- dividends

    function _eligible(address a) private view returns (bool) {
        return !taxExempt[a] && !taxedPools[a] && a != address(this) && balanceOf(a) >= minShare;
    }

    /// @dev Пересчёт теневого дивидендного баланса адреса после изменения его
    ///      обычного баланса (или статуса). Коррекции — как в классической
    ///      magnified-схеме, чтобы прошлое не переписывалось.
    function _refreshDivBalance(address a) private {
        if (a == address(0)) return;
        uint256 nb = _eligible(a) ? balanceOf(a) : 0;
        uint256 ob = divBalance[a];
        if (nb == ob) return;
        if (nb > ob) {
            corrections[a] -= int256(magnifiedDividendPerShare * (nb - ob));
            divSupply += nb - ob;
        } else {
            corrections[a] += int256(magnifiedDividendPerShare * (ob - nb));
            divSupply -= ob - nb;
        }
        divBalance[a] = nb;
    }

    function _afterMove(address from, address to) private {
        _refreshDivBalance(from);
        _refreshDivBalance(to);
    }

    function accumulativeDividendOf(address a) public view returns (uint256) {
        return uint256(int256(magnifiedDividendPerShare * divBalance[a]) + corrections[a]) / MAG;
    }

    function withdrawableDividendOf(address a) public view returns (uint256) {
        return accumulativeDividendOf(a) - withdrawn[a];
    }

    /// @notice Забрать накопленные дивиденды (в этом токене).
    function claim() external returns (uint256 amount) {
        amount = withdrawableDividendOf(msg.sender);
        if (amount > 0) {
            withdrawn[msg.sender] += amount;
            _inTax = true;
            super._update(address(this), msg.sender, amount);
            _inTax = false;
            _refreshDivBalance(msg.sender);
            emit DividendClaimed(msg.sender, amount);
        }
    }

    // ---------------------------------------------------------------- lp

    /// @notice Отправить накопленную ликвидностную долю в lpSink. Может любой.
    function flushLp() external {
        uint256 amount = lpReserve;
        require(amount > 0, "nothing to flush");
        lpReserve = 0;
        _inTax = true;
        super._update(address(this), lpSink, amount);
        _inTax = false;
        emit LpFlushed(amount);
    }
}

